import{c as r,Q as d,j as e,m as o}from"./chunks/framework.rWdQudnF.js";const c=JSON.parse('{"title":"架构师-备考 综合知识-软件工程-软件设计","description":"","frontmatter":{"title":"架构师-备考 综合知识-软件工程-软件设计"},"headers":[],"relativePath":"综合知识/软件工程/软件设计.md","filePath":"综合知识/软件工程/软件设计.md","lastUpdated":null}'),n={name:"综合知识/软件工程/软件设计.md"};function a(l,t,s,g,h,i){return d(),e("div",null,[...t[0]||(t[0]=[o('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 逆向工程（4 个级别/重构/设计恢复/再工程/正向工程）</li><li>[x] 处理流程设计（PFD/IPO/N-S 图/PAD/BPR/BPM）</li><li>[x] 系统设计（概要设计/详细设计/基本原理/设计原则）</li><li>[x] 模块化设计（内聚 7 级/耦合 7 级）</li><li>[x] 人机界面设计（三大黄金原则）</li><li>[x] 结构化设计工具</li><li>[x] 系统运行与维护（遗留系统/系统转换/维护类型）</li><li>[x] 软件文档分类</li><li>[x] 系统转换方式（直接/并行/分段/渐进式）</li><li>[x] 维护类型辨析（改正性/适应性/完善性/预防性）</li><li>[x] 遗留系统处置补充</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、逆向工程-★" tabindex="-1">一、逆向工程 ★ <a class="header-anchor" href="#一、逆向工程-★" aria-label="Permalink to &quot;一、逆向工程 ★&quot;">​</a></h3><blockquote><p>逆向工程：分析已有程序，在比源代码更高抽象层次上建立程序表示的过程。目的是理解程序、恢复设计、软件复用、改进优化。</p></blockquote><p><strong>四个级别（抽象级别从低→高，完备性从高→低）：</strong></p><table tabindex="0"><thead><tr><th>级别</th><th>内容</th><th>备注</th></tr></thead><tbody><tr><td><strong>实现级</strong></td><td>抽象语法树、符号表、过程设计表示</td><td>抽象最低，完备性最高</td></tr><tr><td><strong>结构级</strong></td><td>调用图、结构图、程序和数据结构</td><td>反映程序分量间相互依赖关系</td></tr><tr><td><strong>功能级</strong></td><td>数据和控制流模型</td><td>反映程序段功能及关系</td></tr><tr><td><strong>领域级</strong></td><td>E-R 模型</td><td>抽象最高，完备性最低</td></tr></tbody></table><p><strong>相关概念辨析：</strong></p><table tabindex="0"><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td><strong>重构</strong></td><td>在同一抽象级别上转换系统描述形式，提高可读性和可维护性</td></tr><tr><td><strong>设计恢复</strong></td><td>借助工具从已有程序中抽象出数据设计、结构设计和过程设计信息</td></tr><tr><td><strong>再工程（Re-engineering）</strong></td><td>逆向工程基础上修改或重构已有系统，产生系统<strong>新版本</strong>。包含：逆向工程 → 考虑新需求 → 正向工程</td></tr><tr><td><strong>正向工程</strong></td><td>从现有系统恢复设计信息，改变或重构以改善整体质量</td></tr></tbody></table><blockquote><p>关键辨析：<strong>逆向工程</strong> = 低级别描述→高级别抽象；<strong>再工程</strong> = 逆向 + 修改重构 → 产生新版本。</p></blockquote><hr><h3 id="二、处理流程设计" tabindex="-1">二、处理流程设计 <a class="header-anchor" href="#二、处理流程设计" aria-label="Permalink to &quot;二、处理流程设计&quot;">​</a></h3><p><strong>流程表示工具：</strong></p><table tabindex="0"><thead><tr><th>工具</th><th>特点</th></tr></thead><tbody><tr><td><strong>程序流程图（PFD）</strong></td><td>图框表示操作，独立于语言，由顺序/选择/循环组成</td></tr><tr><td><strong>IPO 图</strong></td><td>描述每个模块的输入、输出和数据加工</td></tr><tr><td><strong>N-S 图（盒图）</strong></td><td>容易表示嵌套和层次关系，结构化强，<strong>不适合复杂程序</strong></td></tr><tr><td><strong>问题分析图（PAD）</strong></td><td>支持结构化程序设计，引导使用结构化方法，逻辑清晰</td></tr></tbody></table><p><strong>BPR（业务流程重组）vs BPM（业务流程管理）：</strong></p><table tabindex="0"><thead><tr><th>对比</th><th>BPR</th><th>BPM</th></tr></thead><tbody><tr><td>核心</td><td>对所有流程进行再造</td><td><strong>不要求对所有流程再造</strong>，根据现有流程规范化设计</td></tr><tr><td>层面</td><td>彻底重构</td><td>三个层面：<strong>规范流程、优化流程、再造流程</strong></td></tr></tbody></table><hr><h3 id="三、系统设计-★" tabindex="-1">三、系统设计 ★ <a class="header-anchor" href="#三、系统设计-★" aria-label="Permalink to &quot;三、系统设计 ★&quot;">​</a></h3><blockquote><p>系统设计目的：为系统制定蓝图，勾画新系统的详细设计方案。</p></blockquote><p><strong>主要内容：</strong></p><ul><li><strong>概要设计</strong>（系统总体结构设计）：功能需求分配给模块，确定模块功能和调用关系 → <strong>模块结构图（系统结构图）</strong></li><li><strong>详细设计</strong>：模块内算法设计、数据结构设计、数据库物理设计、代码/输入输出/界面设计、编写详细设计说明书、评审</li></ul><p><strong>基本原理：</strong></p><table tabindex="0"><thead><tr><th>原理</th><th>说明</th></tr></thead><tbody><tr><td><strong>抽象化</strong></td><td>忽略细节，关注本质</td></tr><tr><td><strong>自顶向下，逐步求精</strong></td><td>从高层到低层逐步细化</td></tr><tr><td><strong>信息隐蔽</strong></td><td>模块内部信息对外不可见</td></tr><tr><td><strong>模块独立</strong></td><td>高内聚、低耦合</td></tr></tbody></table><p><strong>设计原则：</strong> 模块大小适中、减少调用深度、多扇入少扇出、单入口单出口、模块作用域在模块内、功能可预测。</p><h4 id="内聚性-从低→高" tabindex="-1">内聚性（从低→高） <a class="header-anchor" href="#内聚性-从低→高" aria-label="Permalink to &quot;内聚性（从低→高）&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:center;">级别</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;">偶然内聚</td><td>模块内各成分无实质关系</td></tr><tr><td style="text-align:center;">逻辑内聚</td><td>逻辑上相似但功能不同</td></tr><tr><td style="text-align:center;">时间内聚</td><td>同一时间执行（如初始化）</td></tr><tr><td style="text-align:center;">过程内聚</td><td>按特定次序执行</td></tr><tr><td style="text-align:center;">通信内聚</td><td>操作同一数据</td></tr><tr><td style="text-align:center;">顺序内聚</td><td>一个成分的输出是另一个的输入</td></tr><tr><td style="text-align:center;"><strong>功能内聚</strong></td><td>所有成分共同完成单一功能，<strong>最强</strong></td></tr></tbody></table><h4 id="耦合性-从低→高" tabindex="-1">耦合性（从低→高） <a class="header-anchor" href="#耦合性-从低→高" aria-label="Permalink to &quot;耦合性（从低→高）&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:center;">级别</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>无直接耦合</strong></td><td>模块间无直接关系，<strong>最弱</strong></td></tr><tr><td style="text-align:center;">数据耦合</td><td>通过简单数据参数交换</td></tr><tr><td style="text-align:center;">标记耦合</td><td>通过数据结构传递</td></tr><tr><td style="text-align:center;">控制耦合</td><td>传递控制信息影响执行路径</td></tr><tr><td style="text-align:center;">外部耦合</td><td>与外部环境绑定</td></tr><tr><td style="text-align:center;">公共耦合</td><td>共享全局数据</td></tr><tr><td style="text-align:center;">内容耦合</td><td>直接访问另一模块内部数据，<strong>最强</strong></td></tr></tbody></table><hr><h3 id="四、人机界面设计" tabindex="-1">四、人机界面设计 <a class="header-anchor" href="#四、人机界面设计" aria-label="Permalink to &quot;四、人机界面设计&quot;">​</a></h3><p><strong>三大黄金原则：</strong></p><ol><li><strong>置用户于控制之下</strong></li><li><strong>减少用户的记忆负担</strong></li><li><strong>保持界面的一致性</strong></li></ol><hr><h3 id="五、结构化设计工具" tabindex="-1">五、结构化设计工具 <a class="header-anchor" href="#五、结构化设计工具" aria-label="Permalink to &quot;五、结构化设计工具&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>适用范围</th></tr></thead><tbody><tr><td>盒图、HIPO 图、程序流程图</td><td>结构化设计</td></tr><tr><td><strong>顺序图</strong>（Sequence Diagram）</td><td><strong>面向对象设计（UML）</strong>，不属于结构化设计工具</td></tr></tbody></table><hr><h3 id="六、系统运行与维护" tabindex="-1">六、系统运行与维护 <a class="header-anchor" href="#六、系统运行与维护" aria-label="Permalink to &quot;六、系统运行与维护&quot;">​</a></h3><h4 id="遗留系统处置策略" tabindex="-1">遗留系统处置策略 <a class="header-anchor" href="#遗留系统处置策略" aria-label="Permalink to &quot;遗留系统处置策略&quot;">​</a></h4><blockquote><p>遗留系统：不能进行修改和演化以满足新业务需求的信息系统。特点：性能落后、技术过时、无文档、难维护。</p></blockquote><table tabindex="0"><thead><tr><th>策略</th><th>条件</th></tr></thead><tbody><tr><td><strong>淘汰</strong></td><td>低业务价值 + 低系统质量</td></tr><tr><td><strong>继承</strong></td><td>高业务价值 + 低系统质量</td></tr><tr><td><strong>改造</strong></td><td>高业务价值 + 高系统质量</td></tr><tr><td><strong>集成</strong></td><td>低业务价值 + 高系统质量</td></tr></tbody></table><h4 id="系统维护" tabindex="-1">系统维护 <a class="header-anchor" href="#系统维护" aria-label="Permalink to &quot;系统维护&quot;">​</a></h4><p><strong>软件系统文档分类：</strong></p><ul><li><strong>用户文档</strong>：描述系统功能和使用方法，不涉及实现细节</li><li><strong>系统文档</strong>：描述系统设计、实现和测试等详细内容</li></ul><hr><h3 id="七、系统转换方式-★" tabindex="-1">七、系统转换方式 ★ <a class="header-anchor" href="#七、系统转换方式-★" aria-label="Permalink to &quot;七、系统转换方式 ★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：系统转换有4种方式，<strong>并行转换</strong>最安全（新旧系统同时运行一段时间）。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">方式</th><th>说明</th><th style="text-align:center;">风险</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>直接转换</strong></td><td>直接切换到新系统</td><td style="text-align:center;">高</td></tr><tr><td style="text-align:left;"><strong>并行转换</strong></td><td>新旧系统同时运行一段时间，验证后再切换</td><td style="text-align:center;">低</td></tr><tr><td style="text-align:left;"><strong>分段转换</strong></td><td>按模块/区域逐步切换</td><td style="text-align:center;">中</td></tr><tr><td style="text-align:left;"><strong>渐进式转换</strong></td><td>逐步演进替换</td><td style="text-align:center;">中</td></tr></tbody></table><hr><h3 id="八、软件维护类型-★★" tabindex="-1">八、软件维护类型 ★★ <a class="header-anchor" href="#八、软件维护类型-★★" aria-label="Permalink to &quot;八、软件维护类型 ★★&quot;">​</a></h3><blockquote><p>🎯 一句话结论：维护分4种 — <strong>改正性</strong>（修BUG）、<strong>适应性</strong>（适应新环境）、<strong>完善性</strong>（加功能）、<strong>预防性</strong>（用今天方法优化昨天系统为明天需求）。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">类型</th><th>触发原因</th><th>考试关键词</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>改正性维护</strong></td><td>发现性能缺陷/Bug 需要诊断改正</td><td>&quot;发现性能缺陷进行诊断和改正&quot;</td></tr><tr><td style="text-align:left;"><strong>适应性维护</strong></td><td>外部环境变化（新OS、新硬件）</td><td>&quot;适应新操作系统&quot;</td></tr><tr><td style="text-align:left;"><strong>完善性维护</strong></td><td>用户提出新功能/性能要求</td><td>&quot;增加新功能&quot;</td></tr><tr><td style="text-align:left;"><strong>预防性维护</strong></td><td>主动预防未来可能的问题</td><td><strong>&quot;把今天的方法学用于昨天的系统以满足明天的需要&quot;</strong></td></tr></tbody></table><blockquote><p>⚠️ 易错辨析：「改正性」是修复已有错误（被动），「预防性」是主动预防未来问题。</p></blockquote><p><strong>影响软件维护的因素：</strong> 文档质量（是决定因素）、软件复杂度、人员变动等。 <strong>软件可维护性度量：</strong> 外部用 MTTR（平均修复时间），内部用软件复杂性间接度量。 <strong>软件维护阶段占整个生命周期 60% 以上的时间。</strong></p><hr><h3 id="九、遗留系统补充" tabindex="-1">九、遗留系统补充 <a class="header-anchor" href="#九、遗留系统补充" aria-label="Permalink to &quot;九、遗留系统补充&quot;">​</a></h3><blockquote><p>遗留系统特征：维护工作变得越来越困难。处置策略复用已有判断。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:left;">策略</th><th>条件</th><th>记忆</th></tr></thead><tbody><tr><td style="text-align:left;">淘汰</td><td>低业务价值 + 低质量</td><td></td></tr><tr><td style="text-align:left;"><strong>继承</strong></td><td><strong>高业务价值 + 低质量</strong></td><td>业务紧依赖</td></tr><tr><td style="text-align:left;">改造</td><td>高业务价值 + 高质量</td><td></td></tr><tr><td style="text-align:left;"><strong>集成</strong></td><td>低业务价值 + 高质量</td><td>技术含量较高</td></tr></tbody></table><blockquote><p>⚠️ 高频考点：技术含量较高、业务价值较低 → <strong>集成</strong>策略；业务价值高、技术落后 → <strong>继承</strong>策略。</p></blockquote><hr><h3 id="十、软件设计活动" tabindex="-1">十、软件设计活动 <a class="header-anchor" href="#十、软件设计活动" aria-label="Permalink to &quot;十、软件设计活动&quot;">​</a></h3><table tabindex="0"><thead><tr><th>活动</th><th>内容</th></tr></thead><tbody><tr><td><strong>数据设计</strong></td><td>定义数据结构和数据库模式</td></tr><tr><td><strong>架构设计</strong></td><td>确定系统高层结构和组件</td></tr><tr><td><strong>人机界面设计</strong></td><td>设计用户界面和交互方式</td></tr><tr><td><strong>过程设计</strong></td><td>定义业务逻辑和工作流程</td></tr></tbody></table>',61)])])}const x=r(n,[["render",a]]);export{c as __pageData,x as default};
